        json!({"": "x"}),
        json!({"é": "x"}),
        json!({long_key.as_str(): "x"}),
        json!({"a": 1}),
        json!({"a": null}),
        json!({"a": long_value.as_str()}),
        // 129 two-byte characters: under 256 characters, over 256 bytes
        json!({"a": "é".repeat(129)}),
    ] {
